import math
import re
from collections import Counter


def _tokens(text):
    return re.findall(r"[a-z0-9]+", text.lower())


def bm25_rank(query, docs, k1=1.5, b=0.75):
    tokenised = [_tokens(doc) for doc in docs]
    if not tokenised:
        return []
    avgdl = sum(len(doc) for doc in tokenised) / len(tokenised)
    if avgdl == 0:
        return []
    terms = set(_tokens(query))
    holders = {t: sum(1 for doc in tokenised if t in doc) for t in terms}   # n_t: documents containing the term
    idf = {t: math.log(1 + (len(docs) - n + 0.5) / (n + 0.5)) for t, n in holders.items() if n}
    ranked = []
    for index, doc in enumerate(tokenised):
        counts = Counter(doc)
        norm = k1 * (1 - b + b * len(doc) / avgdl)
        score = sum(weight * counts[t] * (k1 + 1) / (counts[t] + norm) for t, weight in idf.items())
        if score > 0:
            ranked.append((index, score))
    ranked.sort(key=lambda pair: (-pair[1], pair[0]))
    return ranked
